# Writes the hedra command files of the glow-worm cave and its props: cave.txt (the floor, the rim of
# boulders, the glow-worm specks on them), stalagmite.txt, crystal.txt (a shard cluster on its own
# stippled pool of light), spark.txt, and halo.png (the stipple every light pool uses). Run from
# models/env: /usr/bin/python3 make_env.py
# hedra: up Z, front -Y (the camera side). World (glTF) = (x, z, -y) of hedra, so a world point
# (wx, wy, wz) is hedra (wx, -wz, wy). Colours exact Cold Light (#08001f, #444d84, #b2d5d1).
import math, os, random
from PIL import Image

HERE = os.path.dirname(os.path.abspath(__file__))
C = {"dark": "0.0314 0.0000 0.1216", "slate": "0.2667 0.3020 0.5176", "pale": "0.6980 0.8353 0.8196"}
def mat(name, col, emit=False):
    s = f"material new {name} --base-color {C[col]} --no-slot"
    return s + (f" --emission {C[col]}" if emit else "")

# The arena (the game reads the same numbers): an ellipse round (0, Z0) in world x/z
A, B, Z0 = 4.0, 2.45, 0.25
# stalagmites, world x/z (scene.bake.json and game.as hold the same list)
PILLARS = [(-1.8, -0.35), (1.95, -0.55), (0.25, 1.5)]

# ---------------------------------------------------------------- halo.png: the light-pool stipple
# 32 x 32, slate where kept, transparent elsewhere: solid in the middle 40 % of the radius, then
# thinning by a 4 x 4 Bayer threshold to nothing at the rim. One texel is about one splat.
BAY = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5]
N = 32
im = Image.new("RGBA", (N, N))
for y in range(N):
    for x in range(N):
        d = math.hypot((x + 0.5) / N - 0.5, (y + 0.5) / N - 0.5) * 2
        keep = max(0.0, min(1.0, (1.0 - d) / 0.6))
        on = (BAY[(x % 4) + (y % 4) * 4] + 0.5) / 16 < keep
        im.putpixel((x, y), (0x44, 0x4D, 0x84, 255) if on else (0x44, 0x4D, 0x84, 0))
im.save(os.path.join(HERE, "halo.png"))

# ---------------------------------------------------------------- floor.png: glints on the cave floor
# 256 x 184 over the 14 x 10 m floor (a texel 0.055 m, under a splat: each glint is one splat): the dark floor with small
# slate glints (wet stone), sparse in the arena's middle and thicker towards the rim. Shade and the
# stalagmites' shadows sink a glint to the dark step, so it also draws the shadows.
fr = random.Random(5)
FW, FH = 256, 184
fl = Image.new("RGBA", (FW, FH), (0x08, 0x00, 0x1F, 255))
for _ in range(2600):
    u, v = fr.random(), fr.random()
    wx, wz = (u - 0.5) * 14, Z0 + (v - 0.5) * 10        # the texture's v runs with world z (top view: +z down)
    e = math.hypot(wx / A, (wz - Z0) / B)
    if fr.random() > 0.12 + 0.6 * min(1.0, max(0.0, e - 0.5)):
        continue
    x, y = int(u * FW), int(v * FH)
    for dx, dy in [(0, 0)]:
        fl.putpixel(((x + dx) % FW, (y + dy) % FH), (0x44, 0x4D, 0x84, 255))
fl.save(os.path.join(HERE, "floor.png"))

def halo(name, r, z=0.03):
    """a flat disc of the stippled pool of light, radius r, just over the floor"""
    return [f"add mesh circle --name {name} --vertices 16 --radius {r} --cap-fill ngon --location 0 0 {z}",
            "material assign Halo", "mode edit", "select all", "uv project-from-view top --scale-to-bounds",
            "mode object"]
HALO_MAT = [f"material new Halo --base-color 1 1 1 --emission {C['slate']} --no-slot",
            "material texture Halo base-color halo.png", "material set Halo alpha-mode mask",
            "material set Halo alpha-cutoff 0.5"]

# ---------------------------------------------------------------- cave
rnd = random.Random(11)
L = ["# The cave: a faceted floor 14 x 10 m (top at y 0, verts jittered so facets catch the light), a",
     "# rim of boulders round the arena ellipse (taller at the back) and a second ring in the corners,",
     "# glow-worm specks (unlit) on the boulders' upper faces. Generated by make_env.py. Up Z, front -Y.",
     "new", "material new Floor --base-color 1 1 1 --no-slot", mat("Rock", "slate"), mat("Speck", "pale", True),
     "add mesh grid --name Floor --x-subdivisions 40 --y-subdivisions 30 --size 1",
     "scale 14 10 1", "apply --scale", f"set location 0 {-Z0:.3f} 0", "apply --location",
     "material assign Floor", "material texture Floor base-color floor.png", "mode edit", "select all",
     "uv project-from-view top --scale-to-bounds", "randomize --amount 0.07 --seed 4",
     # keep the floor's top near 0 (randomize moves all three axes)
     "mode object"]
rocks, specks = [], []
def boulder(i, wx, wz, r, sz, sx=1.0, sy=1.0):
    name = f"Rock{i}"
    rocks.append((wx, wz, r * sx, r * sy, r * sz))
    return [f"add mesh ico-sphere --name {name} --subdivisions 1 --radius {r:.3f} --location {wx:.3f} {-wz:.3f} 0 "
            f"--rotation {rnd.uniform(0, 60):.0f} {rnd.uniform(0, 60):.0f} {rnd.uniform(0, 180):.0f}",
            "apply --rotation", f"scale {sx:.2f} {sy:.2f} {sz:.2f}", "apply --scale",
            "mode edit", "select all", f"randomize --amount {r * 0.12:.3f} --seed {i + 1}",
            # the buried bottom half bakes for nothing: drop the faces under the floor
            'select face where "pos.z < -0.12"', "delete only-faces", "mode object", "material assign Rock"]
k = 0
n1 = 40
for j in range(n1):
    t = (j + rnd.uniform(-0.25, 0.25)) / n1 * 2 * math.pi
    s = math.sin(t)                         # world z = Z0 + (B + ...) * sin: s < 0 is the back
    back = max(0.0, -s)
    rr = rnd.uniform(0.5, 0.72) + 0.25 * back
    wx = (A + 0.45 + rr * 0.6) * math.cos(t)
    wz = Z0 + (B + 0.4 + rr * 0.6) * s
    h = 0.55 + 1.4 * back ** 1.5 + rnd.uniform(-0.1, 0.25)   # low at the front, tall at the back
    L += boulder(k, wx, wz, rr, h / rr * 0.9, rnd.uniform(0.9, 1.3), rnd.uniform(0.9, 1.2)); k += 1
for j in range(26):
    t = (j + rnd.uniform(-0.3, 0.3)) / 22 * 2 * math.pi
    s = math.sin(t)
    back = max(0.0, -s)
    rr = rnd.uniform(0.7, 1.1)
    wx = (A + 1.6 + rr * 0.5) * math.cos(t)
    wz = Z0 + (B + 1.4 + rr * 0.5) * s
    h = 0.8 + 1.8 * back + rnd.uniform(0, 0.4)
    L += boulder(k, wx, wz, rr, h / rr * 0.9, rnd.uniform(1.0, 1.4), 1.0); k += 1
# glow-worm specks: on the upper, camera-facing faces of the rim boulders (a starry cave)
for i in range(110):
    wx, wz, rx, rz_, ry = rocks[rnd.randrange(len(rocks))]
    a = rnd.uniform(0, 2 * math.pi); e = rnd.uniform(0.35, 1.1)
    nx, nz, ny = math.cos(a) * math.cos(e), math.sin(a) * math.cos(e), math.sin(e)
    if nz < -0.2:                            # keep them off the far side
        nz = -nz
    px, pz, py = wx + nx * rx * 0.92, wz + nz * rz_ * 0.92, ny * ry * 0.9
    if abs(px) < A + 0.15 and abs(pz - Z0) < B + 0.15:
        continue
    size = 0.11 if rnd.random() < 0.25 else 0.08
    specks.append(f"S{i}")
    L.append(f"add mesh cube --name S{i} --size {size} --location {px:.3f} {-pz:.3f} {py:.3f}")
L += ["select " + " ".join(specks), f"active {specks[0]}", "join", f"rename {specks[0]} Specks",
      "material assign Speck",
      "select all", "shade flat", "export cave.glb"]
open(os.path.join(HERE, "cave.txt"), "w").write("\n".join(L) + "\n")

# ---------------------------------------------------------------- stalagmite (a deadly pillar)
open(os.path.join(HERE, "stalagmite.txt"), "w").write(f"""# A stalagmite: a tall 6-sided spire 1.15 m with two shorter ones leaning on it, on a rubble
# skirt. Stone (slate, shading to the dark, the sun side up to pale). Origin on the floor under the
# big spire. Generated by make_env.py. Up Z, front -Y.
new
{mat("Stone", "slate")}
add mesh cone --name Spire --vertices 6 --radius1 0.3 --radius2 0.05 --depth 1.15 --location 0 0 0.575
add mesh cone --name SpireB --vertices 6 --radius1 0.2 --radius2 0.03 --depth 0.7 --location 0.22 -0.12 0.3 --rotation -8 14 0
apply --rotation
add mesh cone --name SpireC --vertices 5 --radius1 0.16 --radius2 0.03 --depth 0.5 --location -0.2 0.1 0.22 --rotation 10 -16 0
apply --rotation
add mesh ico-sphere --name Skirt --subdivisions 1 --radius 0.42 --location 0 0 0
scale 1 1 0.35
apply --scale
select Spire SpireB SpireC Skirt
active Spire
join
# the joined object's origin is the spire's centre (z 0.575): world coordinates first, so the cut
# below takes the faces under the floor (select ... where reads object-local positions)
apply --location
material assign Stone
mode edit
select face where "pos.z < 0.0"
delete only-faces
select all
randomize --amount 0.025 --seed 9
mode object
shade flat
export stalagmite.glb
""")

# ---------------------------------------------------------------- crystal (the food)
cr = ["# A crystal cluster: a tall hexagonal shard and three shorter ones leaning out, each a prism",
      "# with a pointed tip; the faces turned to +x slate, the rest pale (unlit: they glow). On a stippled pool of",
      "# light (halo.png, alpha-masked) 0.56 m in radius. Origin on the floor. Generated by make_env.py.",
      "new", mat("Shard", "pale", True), mat("Facet", "slate", True)] + HALO_MAT
shards = [(0.0, 0.0, 0.16, 0.40, 0, 0), (0.2, -0.07, 0.11, 0.24, 30, 115),
          (-0.18, -0.09, 0.105, 0.22, 32, 235), (0.02, 0.2, 0.1, 0.2, 28, 0)]
names = []
for i, (x, y, r, h, tilt, az) in enumerate(shards):
    n = f"P{i}"; names.append(n)
    cr += [f"add mesh cylinder --name {n} --vertices 6 --radius {r} --depth {h} --location 0 0 {h / 2:.3f}",
           f"add mesh cone --name T{i} --vertices 6 --radius1 {r} --radius2 0 --depth {r * 1.6:.3f} --location 0 0 {h + r * 0.8:.3f}",
           f"select {n} T{i}", f"active {n}", "join",
           "mode edit", 'select face where "normal.z < -0.9"', "delete only-faces", "mode object",
           f"set rotation {tilt} 0 {az}", "apply --rotation", f"set location {x} {y} 0", "apply --location"]
cr += ["select " + " ".join(names), "active P0", "join", "rename P0 Crystal", "material assign Shard",
       "mode edit", 'select face where "normal.x > 0.5"', "material assign Facet", "mode object"]
cr += halo("Halo", 0.56) + ["select Crystal", "shade flat", "export crystal.glb"]
open(os.path.join(HERE, "crystal.txt"), "w").write("\n".join(cr) + "\n")

# ---------------------------------------------------------------- spark
open(os.path.join(HERE, "spark.txt"), "w").write(f"""# A spark: a pale cube 0.1 m (unlit), thrown when a crystal is eaten or the worm breaks up.
# Generated by make_env.py.
new
{mat("Spark", "pale", True)}
add mesh cube --name Spark --size 0.1 --rotation 30 20 10
material assign Spark
export spark.glb
""")
print("wrote cave.txt stalagmite.txt crystal.txt spark.txt halo.png")
